coding.solution:
#include <iostream>
using namespace std;
int main() {
    int n, threshold;
    cin >> n >> threshold;
    int count = 0, sum = 0;
    for (int i = 0; i < n; ++i) {
        int x;
        cin >> x;
        if (x >= threshold) {
            ++count;
            sum += x;
        }
    }
    cout << count << " " << sum << "\n";
    return 0;
}
